// Codec parity test: the native encoder must produce exactly the bytes committed under
// app/src/test/resources/openai_stream_codec, which the Kotlin unit test decodes back into
// events. The fixtures are generated by core/tools/golden/openai/codec/generate_codec_fixtures.py
// and are the single source of truth for the wire format.
#include <algorithm>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include "agora/core/openai_stream.hpp"
#include "agora/core/openai_stream_codec.hpp"
#include "check.hpp"

namespace {

using agora::core::openai::ChatStreamConsumer;
using agora::core::openai::Error;
using agora::core::openai::Event;
using agora::core::openai::Termination;
using agora::core::openai::ToolCall;

std::vector<std::uint8_t> read_bytes(const std::filesystem::path& path) {
    std::ifstream stream(path, std::ios::binary);
    return std::vector<std::uint8_t>(std::istreambuf_iterator<char>(stream),
                                     std::istreambuf_iterator<char>());
}

std::string describe_mismatch(const std::vector<std::uint8_t>& actual,
                              const std::vector<std::uint8_t>& expected) {
    const std::size_t common = std::min(actual.size(), expected.size());
    std::size_t at = 0;
    while (at < common && actual[at] == expected[at]) ++at;
    std::string message = "first difference at byte " + std::to_string(at) + " (actual " +
                          std::to_string(actual.size()) + " bytes, expected " +
                          std::to_string(expected.size()) + " bytes)";
    const std::size_t from = at > 8 ? at - 8 : 0;
    const std::size_t to = std::min(common, at + 8);
    auto hex = [](std::size_t begin, std::size_t end, const std::vector<std::uint8_t>& bytes) {
        static constexpr char kDigits[] = "0123456789abcdef";
        std::string out;
        for (std::size_t i = begin; i < end; ++i) {
            out.push_back(kDigits[bytes[i] >> 4]);
            out.push_back(kDigits[bytes[i] & 0xF]);
            out.push_back(' ');
        }
        return out;
    };
    message += "; actual [" + hex(from, to, actual) + "] expected [" + hex(from, to, expected) + "]";
    return message;
}

void require_equal(const std::vector<std::uint8_t>& actual,
                   const std::vector<std::uint8_t>& expected) {
    if (actual != expected) {
        throw agora::core::test::Failure(describe_mismatch(actual, expected));
    }
}

ChatStreamConsumer::LineOutcome build_line_outcome() {
    ChatStreamConsumer::LineOutcome outcome;
    outcome.keep_reading = true;

    Event text;
    text.kind = Event::Kind::TextChunk;
    text.text = "Привет 😀\n\t";
    outcome.events.push_back(text);

    Event thought;
    thought.kind = Event::Kind::ThoughtChunk;
    thought.text = "думаю";
    outcome.events.push_back(thought);

    Event update_without_id;
    update_without_id.kind = Event::Kind::ToolCallUpdate;
    update_without_id.stream_key = "call_stream_00000000-0000-4000-8000-000000000001";
    update_without_id.name = "";
    update_without_id.arguments = "{}";
    outcome.events.push_back(update_without_id);

    Event update_with_id;
    update_with_id.kind = Event::Kind::ToolCallUpdate;
    update_with_id.stream_key = "call_stream_00000000-0000-4000-8000-000000000002";
    update_with_id.call_id = "call_ab";
    update_with_id.name = "search";
    update_with_id.arguments = "{\"q\":\"x\"}";
    outcome.events.push_back(update_with_id);

    Event request;
    request.kind = Event::Kind::ToolCallRequest;
    request.call_id = "call_ab";
    request.name = "search";
    request.arguments = "{\"q\":\"x\"}";
    request.stream_key = "call_ab";
    outcome.events.push_back(request);

    Event requests;
    requests.kind = Event::Kind::ToolCallsRequest;
    ToolCall first;
    first.id = "c1";
    first.name = "n1";
    first.arguments = "{}";
    first.stream_key = "c1";
    ToolCall second;
    second.id = "c2";
    second.name = "n2";
    second.arguments = "[]";
    second.signature = "sig2";
    second.stream_key = "c2";
    requests.calls = {first, second};
    outcome.events.push_back(requests);

    Event usage;
    usage.kind = Event::Kind::UsageUpdate;
    usage.usage.total_token_count = 100;
    usage.usage.input_token_count = 10;
    usage.usage.cache_write_input_token_count = 5;
    usage.usage.output_token_count = 20;
    outcome.events.push_back(usage);

    Event error;
    error.kind = Event::Kind::Error;
    error.error.kind = Error::Kind::SseParse;
    error.error.raw_line = "raw|x";
    error.error.cause = "cause;text\nmore";
    outcome.events.push_back(error);

    return outcome;
}

Termination build_termination() {
    Termination termination;
    termination.saw_terminal_marker = false;
    termination.stop_reason = std::nullopt;
    termination.produced_content = true;
    termination.tool_call_in_flight = true;
    termination.already_reported_error = false;
    termination.timed_out = true;
    termination.stream_error.kind = Error::Kind::IncompleteStream;
    termination.stream_error.provider = "agora";
    termination.stream_error.stop_reason = "length";
    termination.stream_error.tool_call_in_flight = true;
    termination.stream_error.produced_content = true;
    return termination;
}

}  // namespace

TEST(openai_stream_codec_line_outcome_matches_the_shared_fixture) {
    const std::filesystem::path root = AGORA_FIXTURE_OPENAI_CODEC_DIR;
    const std::vector<std::string> logs = {
        "[agora] malformed stream payload exception=JsonDecodingException"};
    const std::vector<std::uint8_t> expected = read_bytes(root / "line_outcome.bin");
    CHECK(!expected.empty());
    require_equal(agora::core::openai::encode_line_outcome(build_line_outcome(), logs), expected);
}

TEST(openai_stream_codec_termination_matches_the_shared_fixture) {
    const std::filesystem::path root = AGORA_FIXTURE_OPENAI_CODEC_DIR;
    const std::vector<std::uint8_t> expected = read_bytes(root / "termination.bin");
    CHECK(!expected.empty());
    require_equal(agora::core::openai::encode_termination(build_termination()), expected);
}
